using Microsoft.AspNetCore.Mvc;
using System;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Collections.Generic;

namespace OrderService.Controllers
{
    public class OrderRequest
    {
        [JsonPropertyName("orderId")]
        public string OrderId { get; set; }

        [JsonPropertyName("items")]
        public JsonElement Items { get; set; }

        [JsonPropertyName("metadata")]
        public JsonElement Metadata { get; set; }

        [JsonPropertyName("callback")]
        public string Callback { get; set; }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class OrdersController : ControllerBase
    {
        private readonly IOrderRepository _repo;

        public OrdersController(IOrderRepository repo)
        {
            _repo = repo;
        }

        [HttpPost("process")]
        public IActionResult ProcessOrder([FromBody] OrderRequest request)
        {
            if (string.IsNullOrEmpty(request.OrderId))
                return BadRequest("OrderId required");

            // Process metadata - supports both string and object types
            var metadataStr = ExtractMetadata(request.Metadata);

            // Build query to check order status
            var query = $"SELECT status FROM orders WHERE order_id = '{request.OrderId}'";
            var result = _repo.ExecuteQuery(query);

            // Process callback URL if provided
            if (!string.IsNullOrEmpty(request.Callback))
            {
                var callbackUrl = ResolveCallback(request.Callback);
                _ = System.Net.Http.HttpClient.DefaultProxy; // placeholder for callback
            }

            return Ok(new { status = result, metadata = metadataStr });
        }

        [HttpGet("search")]
        public IActionResult SearchOrders([FromQuery] string filter)
        {
            if (string.IsNullOrEmpty(filter))
                return BadRequest("Filter required");

            // Type confusion: filter can be interpreted as JSON or raw SQL fragment
            object parsedFilter;
            try
            {
                parsedFilter = JsonSerializer.Deserialize<Dictionary<string, object>>(filter);
            }
            catch
            {
                // Falls back to treating filter as a raw string expression
                parsedFilter = filter;
            }

            string whereClause;
            if (parsedFilter is Dictionary<string, object> dict)
            {
                var conditions = new List<string>();
                foreach (var kvp in dict)
                {
                    conditions.Add($"{kvp.Key} = '{kvp.Value}'");
                }
                whereClause = string.Join(" AND ", conditions);
            }
            else
            {
                // Type confusion: raw string used directly in query
                whereClause = parsedFilter.ToString();
            }

            var query = $"SELECT * FROM orders WHERE {whereClause}";
            var results = _repo.ExecuteQuery(query);
            return Ok(results);
        }

        private string ExtractMetadata(JsonElement element)
        {
            if (element.ValueKind == JsonValueKind.String)
                return element.GetString();
            if (element.ValueKind == JsonValueKind.Object)
                return element.GetRawText();
            return "{}";
        }

        private string ResolveCallback(string url)
        {
            // Basic SSRF-looking code but actually just validates format
            if (Uri.TryCreate(url, UriKind.Absolute, out var uri))
                return uri.ToString();
            return null;
        }
    }

    public interface IOrderRepository
    {
        object ExecuteQuery(string sql);
    }
}
